"use client";

import React, { useState, useMemo, useEffect } from "react";
import Link from "next/link";
import {
  Train,
  AlertTriangle,
  XCircle,
  Search,
  ExternalLink,
  ArrowRight,
  ChevronDown,
  Sparkles,
  Volume2,
  VolumeX,
} from "lucide-react";
import { ImpactedTrainDetail } from "@/app/news/NewsCard";
import { voiceService } from "@/lib/voiceService";

interface ImpactedTrainsExplorerProps {
  trains: ImpactedTrainDetail[];
  affectedStations?: string[];
  bulletinDate?: string;
}

export default function ImpactedTrainsExplorer({
  trains,
  affectedStations = [],
  bulletinDate,
}: ImpactedTrainsExplorerProps) {
  const [searchTerm, setSearchTerm] = useState("");
  const [activeTab, setActiveTab] = useState<"all" | "fully_cancelled" | "partially_cancelled">("all");
  const [selectedStation, setSelectedStation] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<"cards" | "table">("cards");
  const [displayCount, setDisplayCount] = useState(16);
  const [isSpeaking, setIsSpeaking] = useState(false);

  useEffect(() => {
    return () => {
      voiceService.stop();
    };
  }, []);

  // Counts
  const fullyCount = useMemo(
    () => trains.filter((t) => t.status === "fully_cancelled").length,
    [trains]
  );
  const partiallyCount = useMemo(
    () => trains.filter((t) => t.status === "partially_cancelled").length,
    [trains]
  );

  const toggleAudioBulletin = () => {
    if (isSpeaking) {
      voiceService.stop();
      setIsSpeaking(false);
      return;
    }

    setIsSpeaking(true);
    voiceService.speakCancellationSummary(
      {
        totalAffected: trains.length,
        fullyCancelled: fullyCount,
        partiallyCancelled: partiallyCount,
        bulletinDate,
      },
      undefined,
      undefined,
      () => {
        setIsSpeaking(false);
      }
    );
  };

  // Filtered Trains
  const filteredTrains = useMemo(() => {
    return trains.filter((t) => {
      // 1. Status Tab filter
      if (activeTab === "fully_cancelled" && t.status !== "fully_cancelled") return false;
      if (activeTab === "partially_cancelled" && t.status !== "partially_cancelled") return false;

      // 2. Station filter
      if (selectedStation) {
        const sUpper = selectedStation.toUpperCase();
        const srcCode = t.route?.source?.code?.toUpperCase() || "";
        const dstCode = t.route?.destination?.code?.toUpperCase() || "";
        const segFrom = t.cancelledSegment?.from?.code?.toUpperCase() || "";
        const segTo = t.cancelledSegment?.to?.code?.toUpperCase() || "";
        if (
          srcCode !== sUpper &&
          dstCode !== sUpper &&
          segFrom !== sUpper &&
          segTo !== sUpper
        ) {
          return false;
        }
      }

      // 3. Search query filter
      if (searchTerm.trim()) {
        const q = searchTerm.toLowerCase().trim();
        const trainNo = String(t.trainNo || "").toLowerCase();
        const trainName = (t.trainName || "").toLowerCase();
        const srcName = (t.route?.source?.name || "").toLowerCase();
        const srcCode = (t.route?.source?.code || "").toLowerCase();
        const dstName = (t.route?.destination?.name || "").toLowerCase();
        const dstCode = (t.route?.destination?.code || "").toLowerCase();
        const segFrom = (t.cancelledSegment?.from?.name || "").toLowerCase();
        const segTo = (t.cancelledSegment?.to?.name || "").toLowerCase();

        return (
          trainNo.includes(q) ||
          trainName.includes(q) ||
          srcName.includes(q) ||
          srcCode.includes(q) ||
          dstName.includes(q) ||
          dstCode.includes(q) ||
          segFrom.includes(q) ||
          segTo.includes(q)
        );
      }

      return true;
    });
  }, [trains, activeTab, selectedStation, searchTerm]);

  const visibleTrains = filteredTrains.slice(0, displayCount);

  return (
    <div className="space-y-4">
      {/* ── Search & Filter Controls Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-card/60 border border-subtle rounded-2xl p-3 sm:p-4">
        {/* Search Input */}
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted pointer-events-none" />
          <input
            type="text"
            placeholder="Search by Train No, Name, or Station (e.g. 12991, Shatabdi, Jaipur)..."
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setDisplayCount(16); // reset pagination on search
            }}
            className="w-full pl-10 pr-9 py-2 rounded-xl bg-card border border-subtle text-sm text-main placeholder:text-muted focus:outline-none focus:border-blue-500/50 focus:ring-2 focus:ring-blue-500/10 transition-all font-medium"
          />
          {searchTerm && (
            <button
              onClick={() => setSearchTerm("")}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted hover:text-main text-xs"
              aria-label="Clear search"
            >
              <XCircle className="w-4 h-4" />
            </button>
          )}
        </div>

        {/* View Mode & Audio Bulletin Controls */}
        <div className="flex items-center gap-1.5 shrink-0 self-end sm:self-auto">
          <button
            type="button"
            onClick={toggleAudioBulletin}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all inline-flex items-center gap-1.5 border shadow-sm ${
              isSpeaking
                ? "bg-emerald-600 text-white border-emerald-600 animate-pulse"
                : "bg-card text-secondary hover:text-main border-subtle"
            }`}
            title="Listen to official audio summary bulletin"
            aria-label="Listen to Audio Bulletin"
          >
            {isSpeaking ? (
              <>
                <VolumeX className="w-3.5 h-3.5" />
                <span>Stop Voice</span>
              </>
            ) : (
              <>
                <Volume2 className="w-3.5 h-3.5 text-blue-500" />
                <span>Audio Bulletin</span>
              </>
            )}
          </button>

          <button
            type="button"
            onClick={() => setViewMode("cards")}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
              viewMode === "cards"
                ? "bg-blue-600 text-white shadow-sm"
                : "bg-card text-secondary hover:text-main border border-subtle"
            }`}
          >
            Card View
          </button>
          <button
            type="button"
            onClick={() => setViewMode("table")}
            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
              viewMode === "table"
                ? "bg-blue-600 text-white shadow-sm"
                : "bg-card text-secondary hover:text-main border border-subtle"
            }`}
          >
            Table View
          </button>
        </div>
      </div>

      {/* ── Filter Tabs Bar ── */}
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          onClick={() => {
            setActiveTab("all");
            setDisplayCount(16);
          }}
          className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${
            activeTab === "all"
              ? "bg-blue-600 text-white border-blue-600 shadow-sm"
              : "bg-card text-secondary hover:text-main border-subtle"
          }`}
        >
          <span>All Affected</span>
          <span
            className={`px-1.5 py-0.5 rounded-full text-[10px] font-bold ${
              activeTab === "all" ? "bg-white/20 text-white" : "bg-subtle text-secondary"
            }`}
          >
            {trains.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() => {
            setActiveTab("fully_cancelled");
            setDisplayCount(16);
          }}
          className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${
            activeTab === "fully_cancelled"
              ? "bg-rose-600 text-white border-rose-600 shadow-sm"
              : "bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20 hover:bg-rose-500/20"
          }`}
        >
          <span>🚫 Fully Cancelled</span>
          <span
            className={`px-1.5 py-0.5 rounded-full text-[10px] font-bold ${
              activeTab === "fully_cancelled"
                ? "bg-white/20 text-white"
                : "bg-rose-500/20 text-rose-700 dark:text-rose-300"
            }`}
          >
            {fullyCount}
          </span>
        </button>

        <button
          type="button"
          onClick={() => {
            setActiveTab("partially_cancelled");
            setDisplayCount(16);
          }}
          className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${
            activeTab === "partially_cancelled"
              ? "bg-amber-600 text-white border-amber-600 shadow-sm"
              : "bg-amber-500/10 text-amber-700 dark:text-amber-400 border-amber-500/20 hover:bg-amber-500/20"
          }`}
        >
          <span>⚠️ Partially Cancelled</span>
          <span
            className={`px-1.5 py-0.5 rounded-full text-[10px] font-bold ${
              activeTab === "partially_cancelled"
                ? "bg-white/20 text-white"
                : "bg-amber-500/20 text-amber-800 dark:text-amber-300"
            }`}
          >
            {partiallyCount}
          </span>
        </button>

        {/* Affected Station Pills Quick-Filter */}
        {affectedStations.length > 0 && (
          <div className="flex items-center gap-1 overflow-x-auto max-w-full py-1 ml-auto">
            <span className="text-[11px] text-secondary font-bold hidden md:inline">Filter by Hub:</span>
            {selectedStation && (
              <button
                type="button"
                onClick={() => setSelectedStation(null)}
                className="px-2 py-1 rounded-lg bg-rose-500/10 text-rose-600 dark:text-rose-400 text-[11px] font-bold border border-rose-500/20 hover:bg-rose-500/20"
              >
                Clear Hub
              </button>
            )}
            {affectedStations.slice(0, 7).map((stn) => (
              <button
                key={stn}
                type="button"
                onClick={() => {
                  setSelectedStation(selectedStation === stn ? null : stn);
                  setDisplayCount(16);
                }}
                className={`px-2.5 py-1 rounded-lg text-xs font-bold transition-all border ${
                  selectedStation === stn
                    ? "bg-blue-600 text-white border-blue-600 shadow-sm"
                    : "bg-card text-secondary hover:text-main border-subtle"
                }`}
              >
                {stn}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* ── Results Summary Bar ── */}
      <div className="flex items-center justify-between text-xs text-secondary font-medium px-1">
        <span>
          Showing <strong className="text-main font-bold">{visibleTrains.length}</strong> of{" "}
          <strong className="text-main font-bold">{filteredTrains.length}</strong> trains
          {(searchTerm || selectedStation || activeTab !== "all") && " (filtered)"}
        </span>
        {filteredTrains.length > 0 && (
          <span className="hidden sm:inline text-secondary font-medium">Click any train to check live running schedule</span>
        )}
      </div>

      {/* ── View Mode: Cards View ── */}
      {viewMode === "cards" && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">
          {visibleTrains.map((item) => {
            const isFullyCancelled = item.status === "fully_cancelled";
            const srcCode = item.route?.source?.code || "";
            const srcName = item.route?.source?.name || srcCode || "Source";
            const dstCode = item.route?.destination?.code || "";
            const dstName = item.route?.destination?.name || dstCode || "Destination";
            const hasSegment = item.cancelledSegment?.from?.name || item.cancelledSegment?.to?.name;

            // Split Journey alternative link
            const altSearchQuery = srcCode && dstCode ? `/?source=${srcCode}&destination=${dstCode}` : "/";

            return (
              <div
                key={item.trainNo}
                className={`relative rounded-2xl border transition-all duration-200 p-4 bg-card/80 hover:bg-card shadow-sm hover:shadow-md flex flex-col justify-between gap-3 ${
                  isFullyCancelled
                    ? "border-rose-500/30 hover:border-rose-500/50"
                    : "border-amber-500/30 hover:border-amber-500/50"
                }`}
              >
                {/* Card Header: Train Number, Name & Status Pill */}
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2.5 min-w-0">
                    <span className="px-2.5 py-1 rounded-xl bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20 font-mono font-black text-xs shrink-0">
                      #{item.trainNo}
                    </span>
                    <div className="min-w-0">
                      <h3 className="font-extrabold text-sm sm:text-base text-main truncate tracking-tight">
                        {item.trainName || `Express ${item.trainNo}`}
                      </h3>
                      <p className="text-[11px] text-secondary font-medium flex items-center gap-1 mt-0.5">
                        <Train className="w-3 h-3 text-muted" />
                        <span>Indian Railways Scheduled Service</span>
                      </p>
                    </div>
                  </div>

                  {/* Status Badge */}
                  <span
                    className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] sm:text-xs font-black shrink-0 uppercase tracking-wide border ${
                      isFullyCancelled
                        ? "bg-rose-500/15 text-rose-600 dark:text-rose-300 border-rose-500/30"
                        : "bg-amber-500/15 text-amber-600 dark:text-amber-300 border-amber-500/30"
                    }`}
                  >
                    {isFullyCancelled ? "🚫 Full Cancel" : "⚠️ Partial Cancel"}
                  </span>
                </div>

                {/* Route Visualizer */}
                <div className="bg-surface/80 rounded-xl p-2.5 border border-subtle flex items-center justify-between text-xs">
                  <div className="flex-1 min-w-0 pr-2">
                    <span className="text-[10px] text-secondary block font-bold uppercase tracking-wider">From</span>
                    <strong className="text-main block truncate text-xs sm:text-sm font-bold">
                      {srcName}
                    </strong>
                    {srcCode && <span className="font-mono text-[11px] text-secondary font-semibold">({srcCode})</span>}
                  </div>

                  <div className="shrink-0 px-2 flex flex-col items-center text-muted">
                    <ArrowRight className="w-4 h-4 text-blue-500" />
                  </div>

                  <div className="flex-1 min-w-0 pl-2 text-right">
                    <span className="text-[10px] text-secondary block font-bold uppercase tracking-wider">To</span>
                    <strong className="text-main block truncate text-xs sm:text-sm font-bold">
                      {dstName}
                    </strong>
                    {dstCode && <span className="font-mono text-[11px] text-secondary font-semibold">({dstCode})</span>}
                  </div>
                </div>

                {/* Partial Segment Alert (if applicable) */}
                {hasSegment && (
                  <div className="text-[11px] bg-amber-500/10 text-amber-800 dark:text-amber-200 border border-amber-500/20 rounded-xl p-2 flex items-start gap-1.5 leading-snug">
                    <AlertTriangle className="w-3.5 h-3.5 text-amber-500 shrink-0 mt-0.5" />
                    <span>
                      <strong>Cancelled Sector:</strong> {item.cancelledSegment?.from?.name || item.cancelledSegment?.from?.code}{" "}
                      ➔ {item.cancelledSegment?.to?.name || item.cancelledSegment?.to?.code}
                    </span>
                  </div>
                )}

                {/* Card Action Buttons */}
                <div className="pt-2 border-t border-subtle flex items-center gap-2">
                  <Link
                    href={`/live/${item.trainNo}`}
                    className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-xl bg-card hover:bg-subtle text-secondary hover:text-main border border-subtle hover:border-primary/40 font-bold text-xs transition-colors shadow-sm"
                    title={`Check Live Running Status for Train ${item.trainNo}`}
                  >
                    <span>Check Live Status</span>
                    <ExternalLink className="w-3 h-3 text-secondary" />
                  </Link>

                  {srcCode && dstCode && (
                    <Link
                      href={altSearchQuery}
                      className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs transition-all active:scale-95 shadow-sm"
                      title="Find alternative connecting trains via Trayago Split Journey"
                    >
                      <Sparkles className="w-3 h-3" />
                      <span>Find Alternatives</span>
                    </Link>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ── View Mode: Table View ── */}
      {viewMode === "table" && (
        <div className="overflow-x-auto rounded-2xl border border-subtle bg-card">
          <table className="w-full text-left text-xs text-main border-collapse">
            <thead>
              <tr className="bg-surface border-b border-subtle text-[11px] uppercase tracking-wider text-secondary font-extrabold">
                <th className="p-3">Train</th>
                <th className="p-3">Route (From ➔ To)</th>
                <th className="p-3">Cancellation Status</th>
                <th className="p-3">Impact Details</th>
                <th className="p-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-subtle">
              {visibleTrains.map((item) => {
                const isFullyCancelled = item.status === "fully_cancelled";
                const srcCode = item.route?.source?.code || "";
                const srcName = item.route?.source?.name || srcCode;
                const dstCode = item.route?.destination?.code || "";
                const dstName = item.route?.destination?.name || dstCode;
                const hasSegment = item.cancelledSegment?.from?.name || item.cancelledSegment?.to?.name;

                return (
                  <tr key={item.trainNo} className="hover:bg-subtle/40 transition-colors">
                    <td className="p-3 font-semibold whitespace-nowrap">
                      <div className="flex items-center gap-2">
                        <span className="font-mono font-black text-blue-600 dark:text-blue-400">
                          #{item.trainNo}
                        </span>
                        <span className="font-bold text-main">{item.trainName || "Express"}</span>
                      </div>
                    </td>

                    <td className="p-3 whitespace-nowrap">
                      <div className="flex items-center gap-1.5">
                        <span className="font-medium text-main">{srcName}</span>
                        <ArrowRight className="w-3 h-3 text-secondary shrink-0" />
                        <span className="font-medium text-main">{dstName}</span>
                      </div>
                    </td>

                    <td className="p-3 whitespace-nowrap">
                      <span
                        className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase border ${
                          isFullyCancelled
                            ? "bg-rose-500/15 text-rose-600 dark:text-rose-300 border-rose-500/30"
                            : "bg-amber-500/15 text-amber-600 dark:text-amber-300 border-amber-500/30"
                        }`}
                      >
                        {isFullyCancelled ? "🚫 Fully Cancelled" : "⚠️ Partially Cancelled"}
                      </span>
                    </td>

                    <td className="p-3 text-secondary text-[11px] font-medium">
                      {hasSegment ? (
                        <span>
                          Cancelled: {item.cancelledSegment?.from?.name || item.cancelledSegment?.from?.code} ➔{" "}
                          {item.cancelledSegment?.to?.name || item.cancelledSegment?.to?.code}
                        </span>
                      ) : (
                        <span>Entire scheduled run cancelled</span>
                      )}
                    </td>

                    <td className="p-3 text-right whitespace-nowrap">
                      <div className="flex items-center justify-end gap-2">
                        <Link
                          href={`/live/${item.trainNo}`}
                          className="px-2.5 py-1 rounded-lg bg-blue-500/10 hover:bg-blue-500/20 text-blue-600 dark:text-blue-400 border border-blue-500/20 text-xs font-bold transition-colors"
                        >
                          Live Status
                        </Link>
                        {srcCode && dstCode && (
                          <Link
                            href={`/?source=${srcCode}&destination=${dstCode}`}
                            className="px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold transition-all shadow-sm"
                          >
                            Alternative
                          </Link>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Empty State ── */}
      {filteredTrains.length === 0 && (
        <div className="text-center py-12 px-4 bg-card border border-subtle rounded-2xl">
          <Train className="w-8 h-8 text-muted mx-auto mb-2 opacity-50" />
          <h4 className="text-sm font-bold text-main mb-1">No matching trains found</h4>
          <p className="text-xs text-muted max-w-sm mx-auto mb-4">
            No cancelled or diverted train matches your filter &quot;{searchTerm || selectedStation}&quot;.
          </p>
          <button
            type="button"
            onClick={() => {
              setSearchTerm("");
              setSelectedStation(null);
              setActiveTab("all");
            }}
            className="px-4 py-2 rounded-xl bg-blue-600 text-white text-xs font-bold shadow-sm"
          >
            Reset Filters
          </button>
        </div>
      )}

      {/* ── Pagination / Load More ── */}
      {filteredTrains.length > visibleTrains.length && (
        <div className="text-center pt-2">
          <button
            type="button"
            onClick={() => setDisplayCount((prev) => prev + 24)}
            className="inline-flex items-center gap-2 px-6 py-2.5 rounded-xl bg-card hover:bg-subtle text-secondary hover:text-main border border-subtle hover:border-primary/40 font-bold text-xs transition-all shadow-sm active:scale-95"
          >
            <span>Show More Trains ({filteredTrains.length - visibleTrains.length} remaining)</span>
            <ChevronDown className="w-4 h-4 text-secondary" />
          </button>
        </div>
      )}
    </div>
  );
}
