import axios from 'axios';
import { getOrCreateDeviceId } from './deviceIdentity';

export function getApiBaseUrl(rawUrl: string): string {
  if (rawUrl && rawUrl.trim().length > 0) {
    let url = rawUrl.replace(/\/+$/, '');
    if (!/\/api$/i.test(url)) {
      url += '/api';
    }
    return url;
  }
  if (typeof window !== 'undefined') {
    const host = window.location.hostname;
    if (host === 'localhost' || host === '127.0.0.1') {
      return 'http://localhost:5000/api';
    }
    return 'https://app.trayago.in/api';
  }
  if (process.env.NODE_ENV === 'production') {
    return 'https://app.trayago.in/api';
  }
  return 'http://localhost:5000/api';
}

const rawApiUrl = process.env.NEXT_PUBLIC_API_URL || '';
export const API_BASE = getApiBaseUrl(rawApiUrl);
export const API_HOST = API_BASE.replace(/\/api$/, '');

// Set global axios credentials so cookies are always preserved across subdomains
axios.defaults.withCredentials = true;

/**
 * Endpoints that do not require and must never send an expired/stale Authorization header,
 * and must not trigger proactive or reactive refresh loops.
 */
export function isPublicAuthEndpoint(url?: string): boolean {
  if (!url) return false;
  const cleanUrl = url.toLowerCase();
  const publicPaths = [
    '/auth/login',
    '/auth/google-login',
    '/auth/signup',
    '/auth/send-otp',
    '/auth/verify-otp',
    '/auth/forgot-password',
    '/auth/reset-password',
    '/auth/csrf-token',
    '/auth/refresh',
    '/auth/ping-auth'
  ];
  return publicPaths.some(p => cleanUrl.includes(p));
}

const api = axios.create({
  baseURL: API_BASE,
  withCredentials: true,
  headers: {
    'Content-Type': 'application/json',
  },
});

api.interceptors.request.use((config) => {
  if (typeof window !== 'undefined') {
    const sessionId = localStorage.getItem('trayago_session');
    if (sessionId) {
      config.headers['x-session-id'] = sessionId;
    }
    const token = localStorage.getItem('accessToken');
    if (token && !config.headers['Authorization'] && !isPublicAuthEndpoint(config.url)) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }
    if (!config.headers['x-device-id']) {
      config.headers['x-device-id'] = getOrCreateDeviceId();
    }
    const betaCode = localStorage.getItem('betaCode');
    if (betaCode && !config.headers['x-beta-code']) {
      config.headers['x-beta-code'] = betaCode;
    }
  }
  return config;
});

export const searchTrains = async (from: string, to: string, date?: string) => {
  try {
    const response = await api.get('/trains/searchAdvanced', {
      params: { from, to, date },
    });
    const trains = response.data.trains || [];
    return {
      trains: trains,
      split: response.data.split || [],
      source: response.data.source
    };
  } catch (error) {
    throw error;
  }
};

