export const getInviteStats = async (_sessionId: string) => {
  try {
    const userRaw = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    const user = userRaw ? JSON.parse(userRaw) : null;
    const userId = user?.id;

    if (!userId) {
      return { success: false, message: 'Missing user id' };
    }

    const response = await api.get('/referrals/stats', {
      headers: { 'x-user-id': userId }
    });

    return {
      success: !!response.data?.success,
      data: {
        referral_code: response.data?.data?.referralCode || null,
        referral_count: response.data?.data?.inviteCount || 0
      }
    };
  } catch (error) {
    console.error('API Error (getInviteStats):', error);
    return { success: false, message: 'Failed to load referral info' };
  }
};

export const claimReferral = async (_sessionId: string, refCode: string) => {
  try {
    const userRaw = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    const user = userRaw ? JSON.parse(userRaw) : null;
    const userId = user?.id;
    if (!userId) {
      return { success: false, message: 'Missing user id' };
    }

    const response = await api.post('/referrals/apply', { referralCode: refCode }, {
      headers: { 'x-user-id': userId }
    });

    return {
      success: !!response.data?.success,
      message: response.data?.message || 'Referral applied',
      data: response.data?.data
    };
  } catch (error: any) {
    return {
      success: false,
      message: error?.response?.data?.error || 'Invalid code'
    };
  }
};

// ── New typed referral API ───────────────────────────────────────────────────

export interface ReferralStats {
  referralCode: string | null;
  inviteCount: number;
  creditsEarned: number;
  nextMilestone: number;
  progressPct: number;
  rewardStatus: 'unlocked' | 'pending';
  recentReferrals: { referredUserId: string; createdAt: string }[];
}

function getCurrentUserId(): string | null {
  if (typeof window === 'undefined') return null;
  try {
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    return user?.id ?? null;
  } catch {
    return null;
  }
}

export const getReferralStats = async (): Promise<{ success: boolean; data?: ReferralStats; error?: string }> => {
  const userId = getCurrentUserId();
  if (!userId) return { success: false, error: 'Not logged in' };
  try {
    const res = await api.get('/referrals/stats', { headers: { 'x-user-id': userId } });
    return { success: true, data: res.data?.data as ReferralStats };
  } catch (err: any) {
    return { success: false, error: err?.response?.data?.error || 'Failed to load stats' };
  }
};

export const applyReferralCodeApi = async (
  referralCode: string,
  deviceFingerprint?: string
): Promise<{ success: boolean; message?: string; data?: any }> => {
  const userId = getCurrentUserId();
  if (!userId) return { success: false, message: 'Not logged in' };
  try {
    const res = await api.post(
      '/referrals/apply',
      { referralCode, deviceFingerprint },
      { headers: { 'x-user-id': userId } }
    );
    return { success: true, message: res.data?.message, data: res.data?.data };
  } catch (err: any) {
    return { success: false, message: err?.response?.data?.error || 'Invalid code' };
  }
};

export default api;
